@Composable
fun AppNav(navController: NavHostController) {
  NavHost(navController, startDestination = "checkout") {
    navigation(startDestination = "cart/list", route = "checkout") {
      composable("cart/list") { entry ->
        // owner = this back stack entry -> an instance of its own
        val own: CartViewModel = hiltViewModel()

        // owner = the "checkout" graph entry -> shared by every screen in the flow
        // and cleared when the flow is popped
        val parent = remember(entry) { navController.getBackStackEntry("checkout") }
        val shared: CartViewModel = hiltViewModel(parent)

        CartList(own, shared)
      }
      // hiltViewModel() here is a third, different instance
      composable("cart/summary") { CartSummary(hiltViewModel()) }
    }
  }
}

