@Scope @Retention(AnnotationRetention.RUNTIME) annotation class SessionScope

@DefineComponent(parent = SingletonComponent::class)
interface SessionComponent

@DefineComponent.Builder
interface SessionComponentBuilder {
  fun user(@BindsInstance user: User): SessionComponentBuilder
  fun build(): SessionComponent
}

// A custom component is reached through an entry point, never @AndroidEntryPoint
@EntryPoint
@InstallIn(SessionComponent::class)
interface SessionEntryPoint {
  fun orders(): OrderRepository
}

@SessionScope
class OrderRepository @Inject constructor(
  private val user: User,
  private val api: OrderApi
) {
  private val cache = mutableMapOf<String, Order>()   // dies with the session, not the process
}

@Singleton
class SessionManager @Inject constructor(
  private val builder: Provider<SessionComponentBuilder>
) {
  private var component: SessionComponent? = null

  fun login(user: User) { component = builder.get().user(user).build() }
  fun logout() { component = null }                   // the whole subgraph becomes collectable

  fun orders(): OrderRepository = EntryPoints
    .get(requireNotNull(component), SessionEntryPoint::class.java)
    .orders()
}
